#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# ──────────────────────────────────────────────────────────────────────────

REPO_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
ENV_FILE="$REPO_DIR/.env.local"
SCHEMA_FILE="$REPO_DIR/supabase/schema.sql"

TOTAL_STAGES=6

banner "Facebook Wall: Supabase + Vercel setup"

# ── Stage 1: create the Supabase project ──────────────────────────────────
stage "Supabase: create the project"
say "First we need a Supabase project to hold the wall's posts."
open_url "https://supabase.com/dashboard/projects"
step "Sign in (GitHub login is easiest)."
step "Click 'New project'."
step "Name it 'facebook-wall', set a database password (save it somewhere),"
step "pick the region closest to you, and click 'Create new project'."
say ""
note "Provisioning takes a minute or two; wait for the project page to load."
pause "Press Enter when the project is ready."

# ── Stage 2: run the schema SQL ───────────────────────────────────────────
stage "Supabase: create the posts table"
say "Now run the schema (table + RLS policies + realtime) in the SQL Editor."
step "In your project's left sidebar, open 'SQL Editor'."
step "Paste the SQL below (also in supabase/schema.sql) and click 'Run'."
say ""
sed 's/^/    /' "$SCHEMA_FILE"
say ""
note "Expected result: 'Success. No rows returned'."
pause "Press Enter once the SQL has run successfully."

# ── Stage 3: capture the keys ─────────────────────────────────────────────
stage "Supabase: project URL + anon key"
say "Two values connect the app to this project; both are safe to be public."
step "In the left sidebar, open 'Project Settings' (gear icon)."
step "Under 'Data API', copy the 'Project URL' (https://xxxxx.supabase.co)."
ask NEXT_PUBLIC_SUPABASE_URL "Paste the Project URL:"
step "Now open 'API Keys' in Project Settings."
step "Copy the anon/public key (starts 'eyJ...'). If you only see a"
step "'Publishable key' (starts 'sb_publishable_'), that works too."
ask NEXT_PUBLIC_SUPABASE_ANON_KEY "Paste the key:"
write_env NEXT_PUBLIC_SUPABASE_URL "$NEXT_PUBLIC_SUPABASE_URL"
write_env NEXT_PUBLIC_SUPABASE_ANON_KEY "$NEXT_PUBLIC_SUPABASE_ANON_KEY"
say ""
say "Checking the database from here..."
if resp=$(curl -s --max-time 15 \
      "$NEXT_PUBLIC_SUPABASE_URL/rest/v1/posts?select=id&limit=1" \
      -H "apikey: $NEXT_PUBLIC_SUPABASE_ANON_KEY" \
      -H "Authorization: Bearer $NEXT_PUBLIC_SUPABASE_ANON_KEY") \
    && [[ "$resp" == \[* ]]; then
  printf '  %s✓%s posts table is reachable with these keys\n' "$GREEN" "$RESET"
else
  warn "Could not query the posts table (response: ${resp:-no response})."
  warn "Re-check the URL, the key, and that stage 2's SQL ran, then re-run"
  warn "this wizard — saved values are offered again as defaults."
fi

# ── Stage 4: verify locally ───────────────────────────────────────────────
stage "Verify the wall locally"
say "Let's see it working before deploying."
step "In a second terminal:  cd $REPO_DIR && npm run dev"
pause "Press Enter when the dev server says it's ready."
open_url "http://localhost:3000"
step "Write something on the wall and click Share."
step "Real-time check: open localhost:3000 in a second browser window,"
step "post there, and watch it appear in the first window without a refresh."
if confirm "Did the post appear in both windows?"; then
  say "Local setup verified."
else
  warn "If the post didn't save: re-check stage 3's keys in .env.local and"
  warn "restart the dev server (env changes need a restart)."
  warn "If it saved but didn't appear live: re-run stage 2's last SQL line"
  warn "(the realtime publication)."
  pause "Fix it, then press Enter to continue (or Ctrl-C and re-run later)."
fi

# ── Stage 5: deploy on Vercel ─────────────────────────────────────────────
stage "Vercel: import and deploy"
say "Deploy the GitHub repo; every push to main will auto-redeploy."
open_url "https://vercel.com/new"
step "Sign in with GitHub and import 'JeyjeyOsom/facebook-wall'."
step "Before clicking Deploy, expand 'Environment Variables' and add both:"
say ""
say "    NEXT_PUBLIC_SUPABASE_URL"
say "    $NEXT_PUBLIC_SUPABASE_URL"
say ""
say "    NEXT_PUBLIC_SUPABASE_ANON_KEY"
say "    $NEXT_PUBLIC_SUPABASE_ANON_KEY"
say ""
step "Click 'Deploy' and wait for the confetti."
pause "Press Enter when the deployment has finished."

# ── Stage 6: capture the production URL ───────────────────────────────────
stage "Grab the production URL"
say "The challenge wants the PUBLIC production URL, not a preview URL."
step "On the project's page in Vercel, copy the main domain shown under"
step "'Domains' — it looks like https://facebook-wall-xxxx.vercel.app"
note "(Preview URLs contain a git hash or branch name; don't use those.)"
ask PRODUCTION_URL "Paste the production URL:"
open_url "$PRODUCTION_URL"
step "Post one message on the live site to prove the deployment works."
if confirm "Does posting work on the live site?"; then
  say "Deployment verified."
else
  warn "Usual culprit: env vars missing or typo'd in Vercel — check the"
  warn "project's Settings → Environment Variables, then redeploy."
fi
printf '\n  %s★ Your submission URL:%s %s\n' "$BOLD" "$RESET" "$PRODUCTION_URL"
note "Submit it at https://apply.capm.us with the screenshots."
pause

finish
